/* 8-BIT SOUND SYSTEM - Embedded WAVs */
const SOUND_B64 = {
  "shoot": "",
  "hit": "",
  "playerHit": "",
  "powerup": "",
  "ovule": "",
  "levelWin": "",
  "gameOver": "",
  "start": "",
  "multiActivate": "",
};

var _sndCtx = null;
function _getSndCtx() {
  if (!_sndCtx) {
    try { _sndCtx = new (window.AudioContext || window.webkitAudioContext)(); } catch(e) { return null; }
  }
  return _sndCtx;
}

function playSound(key) {
  var ctx = _getSndCtx();
  if (!ctx) return;
  if (ctx.state === "suspended") ctx.resume();
  var b64 = SOUND_B64[key];
  if (!b64) return;
  try {
    var raw = atob(b64);
    var u8 = new Uint8Array(raw.length);
    for (var i = 0; i < raw.length; i++) u8[i] = raw.charCodeAt(i);
    ctx.decodeAudioData(u8.buffer, function(buffer) {
      var src = ctx.createBufferSource();
      src.buffer = buffer;
      var g = ctx.createGain();
      g.gain.value = 0.5;
      src.connect(g);
      g.connect(ctx.destination);
      src.start(0);
    }, function() {});
  } catch(e) {}
}
